void main() {
    // Procedural sprite: a texel whose red is 254 carries its own coordinates in green and blue
    // (0..63, see the orb texture), so the shader knows where it is in the sprite and draws a disk.
    vec4 tex = textureLod(Sampler0, texCoord0, 0.0);
    if (abs(tex.r * 255.0 - 254.0) < 0.5 && tex.a > 0.99) {
        vec2 local = tex.gb * 255.0 / 63.0;            // 0..1 across the sprite
        float d = length(local - 0.5) * 2.0;           // 0 at the center, 1 at the rim
        if (d > 1.0) {
            discard;
        }
        #ifdef OIT_ALPHA_ONLY
        executeAlphaOnlyPhase(gl_FragCoord.z, 1.0);
        return;
        #else
        // Pulse twice a second: a whole number of periods per GameTime wrap (24000 ticks).
        float pulse = 0.85 + 0.15 * sin(GameTime * 6.2831853 * 24000.0 / 10.0);
        float ring = smoothstep(0.05, 0.0, abs(d - 0.8 * pulse));
        vec3 core = mix(vec3(1.0, 0.97, 0.75), vec3(1.0, 0.45, 0.1), d);
        fragColor = vec4(core + ring * vec3(1.0, 0.8, 0.3), 1.0);   // fullbright: no lightmap
        return;
        #endif
    }
